from pathlib import Path
import re,json,hashlib,difflib
P=Path(__file__).resolve().parents[1]; proof=P/'testing/opening-v1';proof.mkdir(parents=True,exist_ok=True)
assert not (proof/'changes.json').exists(),'Already applied'
names=['common.rpy','ria_r01.rpy','ria_r02_r04.rpy','jihyun_r01_r04.rpy','yujin_r01_r04.rpy','seoyun_r01_r04.rpy','options.rpy']
original={n:(P/'game'/n).read_text(encoding='utf-8') for n in names}; sources=dict(original);edits=[]
def q(label,old,new):
 n=next(n for n,t in sources.items() if re.search(r'^label '+label+r'(?:\(|:)',t,re.M))
 t=sources[n];start=re.search(r'^label '+label+r'(?:\(|:)',t,re.M).start();end=t.find('\nlabel ',start+1);end=len(t) if end<0 else end
 body=t[start:end];assert body.count(old)==1,(label,old,body.count(old))
 pos=body.index(old);indent=body[body.rfind('\n',0,pos)+1:pos];assert not indent.strip()
 sources[n]=t[:start]+body.replace(old,new.replace('\n','\n'+indent),1)+t[end:]
 edits.append({'file':n,'label':label,'before':old,'after':new})
def ri(label,speaker,a,b,c,d):q(label,f'{speaker} "[ri(\'{a}\', \'{b}\')]"',f'{speaker} "[ri(\'{c}\', \'{d}\')]"')
# First-day choices now have distinct immediate, physical results.
q('c01','r "좋아요. 말한 사람이 관찰 담당. 제가 옮길게요."','r "좋아요. 제가 옮길게요. 여기? 더 오른쪽?"\n"도현이 입구에 서서 손바닥을 펴자 리아가 표지를 멈춰 세웠다."\nd "거기요. 이번엔 사람들이 안 갈라지네요."')
q('c01','r "좋아요. 저는 표지 앞에서 볼게요. 서로 본 거 맞춰 봐요."','"안내 담당자가 손님들이 두 화살표 사이에서 멈춘다고 짚었다. 도현이 그 자리에 서자 리아가 표지를 돌린다."\nr "아, 거기서는 둘 다 보이네요! 도현 씨, 이번엔 어느 쪽이에요?"\nd "하나요. 이제 저도 길 안 잃겠네요."')
q('c01','r "벌써 역할 나누는 거예요? 좋아요! 끝나고 답 맞춰 봐요~"','r "벌써 역할 나누는 거예요? 좋아요! 입구 쪽 부탁해요~"\n"서로 다른 쪽에 선 두 사람이 동시에 같은 표지를 가리켰다. 리아가 먼저 웃었다."\nr "답은 벌써 맞았네요. 저것만 옮기죠!"')
q('c01','"현장 담당자에게 확인하고 표지를 옮긴다. 입구에서 나뉘던 동선이 한 줄로 모인다."','"현장 담당자와 위치를 확인해 표지를 고정했다. 입구에서 나뉘던 동선이 한 줄로 모인다."')
